def transform(grid):
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])
    for color in set(v for row in a for v in row):
        candidates = []
        for r1 in range(h - 2):
            for r2 in range(r1 + 2, h):
                for c1 in range(w - 2):
                    for c2 in range(c1 + 2, w):
                        if (all(a[r1][c] == color and a[r2][c] == color
                                for c in range(c1, c2 + 1)) and
                            all(a[r][c1] == color and a[r][c2] == color
                                for r in range(r1, r2 + 1))):
                            candidates.append((r1, r2, c1, c2))
        # Only process rectangular outlines whose interior is not the outline color.
        for r1, r2, c1, c2 in sorted(candidates, key=lambda x: (x[1]-x[0])*(x[3]-x[2]), reverse=True):
            interior = [(r, c) for r in range(r1 + 1, r2) for c in range(c1 + 1, c2)]
            if not interior or any(a[r][c] == color for r, c in interior):
                continue
            fill = 7 if len(interior) == 1 else 2
            for r, c in interior:
                a[r][c] = fill
    return a
